import hashlib
import json
import sys
import inspect
import time
from pathlib import Path
import numpy as np
sys.path.insert(0, str(Path(sys.argv[1]) / 'src'))
from patrol_rsi.reorder_execution import run_reorder
from patrol_rsi.local_score import BASE_EXPRESSION
from patrol_rsi.correction_execution import execute_correction
from patrol_rsi.baseline_correction import Rule

def native(v):
    if isinstance(v, np.ndarray): return native(v.tolist())
    if isinstance(v, np.generic): return native(v.item())
    if isinstance(v, dict): return {str(k): native(x) for k, x in v.items()}
    if isinstance(v, (tuple, list)): return [native(x) for x in v]
    return v

def digest(v):
    return hashlib.sha256(json.dumps(native(v), sort_keys=True, separators=(',', ':'), allow_nan=False).encode()).hexdigest()

scenario = 'aux_feeder_loss+cdu_fouling'
spec = {'seed': 41000, 'scenario': scenario, 'duration_s': 180, 'fault_start_s': 335, 'noise_c': .2, 'estimator': 'nominal'}
kind = sys.argv[3]
inputs = []

def stub(context):
    inputs.append({'time_s': float(inspect.currentframe().f_back.f_locals['self'].clock), 'input_sha256': digest(context)})
    return 50. + 20. * context[:, 0].astype(float)

if kind == 'history_stub_T':
    spec['estimator'] = 'history'
    policy = {'method': 'T'}
    record, env = run_reorder(spec, stub, policy)
elif kind == 'nominal_H':
    policy = {'kind': 'correction', 'rule': Rule().to_dict()}
    record, env = execute_correction(spec, None, policy)
else:
    policy = {'method': 'T'} if kind == 'nominal_T' else {'method': 'expression', 'score_expression': BASE_EXPRESSION}
    record, env = run_reorder(spec, None, policy)
metrics = {k:v for k,v in record['metrics'].items() if k != 'history_estimator_inference_s'}
summary = {'case': kind, 'specification': spec, 'policy': policy,
    'process_fingerprint': env.trace.fingerprint,
    'action_sha256': record['action_sha256'],
    'measurements_sha256': digest(record['inspection_events']),
    'assignments_sha256': digest(record['assignments']),
    'exact_task_gaps_sha256': digest(record['exact_task_gaps']),
    'metrics': metrics, 'action_steps': len(record['action_log']),
    'estimator_call_times': [v['time_s'] for v in inputs],
    'stub_input_sha256': inputs, 'stub_only_not_CVAE_scientific_result': bool(inputs)}
Path(sys.argv[2]).write_text(json.dumps(native(summary), ensure_ascii=False, indent=2)+'\n')
print(json.dumps({'case':kind, 'actions':record['action_sha256'], 'completed':metrics['completed_inspections'], 'calls':len(inputs)}),flush=True)

