"""Capture original-engine values; never import or update the migrated engine."""
import gzip
import hashlib
import inspect
import json
import platform
import subprocess
import sys
from pathlib import Path

import numpy as np

original, destination, receipt_path = map(Path, sys.argv[1:4])
receipt = json.loads(receipt_path.read_text())
source_sha = subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=original, text=True).strip()
assert source_sha == receipt['source_commit']
for entry in receipt['source_files']:
    assert hashlib.sha256((original / entry['path']).read_bytes()).hexdigest() == entry['sha256'], entry['path']
sys.path.insert(0, str(original / 'src'))
from patrol_rsi.reorder_execution import run_reorder
from patrol_rsi.correction_execution import execute_correction
from patrol_rsi.baseline_correction import Rule
from patrol_rsi.local_score import BASE_EXPRESSION
from patrol_rsi.inspection_metrics import task_labels

def native(value):
    if isinstance(value, np.ndarray):
        return native(value.tolist())
    if isinstance(value, np.generic):
        return native(value.item())
    if isinstance(value, dict):
        return {str(key): native(item) for key, item in value.items()}
    if isinstance(value, (tuple, list)):
        return [native(item) for item in value]
    return value

def digest(value):
    return hashlib.sha256(json.dumps(native(value), sort_keys=True, separators=(',', ':'), allow_nan=False).encode()).hexdigest()

def array(value):
    value = np.asarray(value)
    return {'dtype': value.dtype.str, 'shape': list(value.shape), 'values': value.tolist()}

spec = {'seed': 41000, 'scenario': 'aux_feeder_loss+cdu_fouling', 'duration_s': 180,
        'fault_start_s': 335, 'noise_c': .2, 'estimator': 'nominal'}
fixture = {'schema': 'core-numeric-reference-v1', 'source_commit': source_sha,
           'source_files': receipt['source_files'], 'specification': spec,
           'environment': {'python': platform.python_version(), 'numpy': np.__version__,
                           'platform': platform.platform(), 'machine': platform.machine()},
           'scope': 'Engineering migration only; deterministic history stub is not a trained CVAE result.',
           'cases': {}}
for name in ('nominal_T', 'nominal_R', 'nominal_H', 'history_stub_T'):
    contexts, call_times = [], []
    def stub(context):
        call_times.append(float(inspect.currentframe().f_back.f_locals['self'].clock))
        contexts.append(context.copy())
        return 50. + 20. * context[:, 0].astype(float)
    case_spec = dict(spec, estimator='history') if name == 'history_stub_T' else spec
    if name == 'nominal_H':
        policy = {'kind': 'correction', 'rule': Rule().to_dict()}
        record, env = execute_correction(case_spec, None, policy)
    else:
        policy = {'method': 'expression', 'score_expression': BASE_EXPRESSION} if name == 'nominal_R' else {'method': 'T'}
        record, env = run_reorder(case_spec, stub if contexts or name == 'history_stub_T' else None, policy)
    archived = next(case['old'] for case in receipt['cases'] if case['id'] == name)
    metrics = {key: value for key, value in record['metrics'].items() if key != 'history_estimator_inference_s'}
    # Original local identity must reproduce the original receipt before capture.
    assert record['action_sha256'] == archived['action_sha256'], name
    assert digest(record['inspection_events']) == archived['measurements_sha256'], name
    assert digest(record['assignments']) == archived['assignments_sha256'], name
    assert digest(record['exact_task_gaps']) == archived['exact_task_gaps_sha256'], name
    assert env.trace.fingerprint == archived['process_fingerprint'], name
    assert native(metrics) == archived['metrics'], name
    if 'process_arrays' not in fixture:
        fixture['process_arrays'] = {key: array(value) for key, value in env.trace.arrays.items()}
        fixture['process_fingerprint'] = env.trace.fingerprint
        fixture['task_label_mask'] = array(task_labels(env)[0])
    fixture['cases'][name] = {'action_sha256': record['action_sha256'],
        'measurements_sha256': digest(record['inspection_events']),
        'assignments_sha256': digest(record['assignments']),
        'exact_task_gaps_sha256': digest(record['exact_task_gaps']),
        'metrics': native(metrics), 'inspection_events': native(record['inspection_events']),
        'anomaly_intervals': native(record['anomaly_intervals']), 'by_role': native(record['by_role']),
        'history_call_times': call_times}
    if contexts:
        fixture['cases'][name]['history_inputs'] = array(np.stack(contexts))
        observed = [{'time_s': time, 'input_sha256': digest(context)} for time, context in zip(call_times, contexts)]
        assert observed == archived['stub_input_sha256']
    print(json.dumps({'case': name, 'matched_original_receipt': True, 'measurements': len(env.events), 'history_calls': len(contexts)}), flush=True)
raw = json.dumps(fixture, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()
compressed = gzip.compress(raw, compresslevel=9, mtime=0)
destination.parent.mkdir(parents=True, exist_ok=True)
destination.write_bytes(compressed)
print(json.dumps({'fixture': str(destination), 'json_bytes': len(raw), 'gzip_bytes': len(compressed),
                  'sha256': hashlib.sha256(compressed).hexdigest()}), flush=True)
